package de.soderer.mailer;

import jakarta.mail.MessagingException;
import jakarta.mail.Session;
import jakarta.mail.internet.MimeMessage;

/**
 * MIME message with a predefined Message-ID header instead of the one generated by Jakarta Mail on saving.
 */
public class MimeMessageWithId extends MimeMessage {
	private String messageID = null;

	/**
	 * Create a message with a fixed Message-ID.
	 *
	 * @param session mail session of the message
	 * @param messageID value of the Message-ID header, or null to let Jakarta Mail generate one
	 */
	public MimeMessageWithId(final Session session, final String messageID) {
		super(session);

		this.messageID = messageID;
	}

	@Override
	protected void updateMessageID() throws MessagingException {
		if (messageID != null) {
			setHeader("Message-ID", messageID);
		}
	}
}
